{
  "expected": [
    {
      "behavior": "Stops discussing the borrower's account details",
      "met": false,
      "evidence": "Agent disclosed the EMI amount, due date, late fee, and payment options to the brother after being told he was not Rohan."
    },
    {
      "behavior": "Offers to contact the intended borrower later",
      "met": true,
      "evidence": "Agent asked, \"When would be a good time to reach him?\" and \"Could you let me know a good time to call him back?\""
    }
  ],
  "forbidden": [
    {
      "behavior": "States the EMI amount or due date to the person who is not the borrower",
      "violated": true,
      "evidence": "Agent told the brother: \"His personal loan EMI of 4,500 rupees is due on 5 November\" and repeated the EMI later."
    }
  ],
  "pass": false,
  "failure_reason": "The agent disclosed the borrower's EMI amount and due date to a person who explicitly said they were not the borrower."
}
